BEGIN;
DO $guard$ BEGIN
IF md5(pg_get_functiondef('private.hub_item_definition(text,text)'::regprocedure)) IS DISTINCT FROM '9dc86596c5e7d9e40a023d5f21638e4b' THEN RAISE EXCEPTION 'Item definitions rollback drift';END IF;
IF md5(pg_get_functiondef('public.admin_item_definitions_read()'::regprocedure)) IS DISTINCT FROM 'c8bd7cc316b5cb3c43d4f67efd80d393' THEN RAISE EXCEPTION 'Item definitions rollback drift';END IF;
IF md5(pg_get_functiondef('public.admin_item_definitions_save(jsonb)'::regprocedure)) IS DISTINCT FROM '632124fd53465d7cb6f409a3592223be' THEN RAISE EXCEPTION 'Item definitions rollback drift';END IF;
IF md5(pg_get_functiondef('public.admin_save_item_identity(text,jsonb)'::regprocedure)) IS DISTINCT FROM '661d77968f0858b621742848dc1da45a' THEN RAISE EXCEPTION 'Item definitions rollback drift';END IF;
END $guard$;
CREATE OR REPLACE FUNCTION public.admin_save_item_identity(p_key text, p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS E'\ndeclare k text := lower(btrim(coalesce(p_key,''''))); cond text;\nbegin\n  perform private.require_staff_edit();\n  cond := coalesce(nullif(p_row->>''conditionType'',''''), (select condition_type from public.capture_balls where key = k));\n  if cond is not null and cond not in (''NONE'',''TARGET_TYPE'',''NIGHT'',''PLAYER_OWNS_SPECIES'',''SPECIES_CATCH_RATE_MIN'',''SPECIES_BASE_SPEED_MIN'',''MOON_STONE_FAMILY'',''SPECIES_WEIGHT_TIERS'',''THROW_EARLY'',''THROW_LATE'',''TRAINER_LEVEL_GTE'',''TARGET_GENDERED'') then\n    raise exception ''That effect type is not supported.'';\n  end if;\n  if exists (select 1 from public.capture_balls where key = k) then\n    update public.capture_balls set\n      name = coalesce(nullif(p_row->>''name'',''''), name),\n      description = coalesce(p_row->>''description'', description),\n      rarity = coalesce(nullif(p_row->>''rarity'',''''), rarity),\n      economic_tier = coalesce(nullif(p_row->>''tier'',''''), economic_tier),\n      shop_price = coalesce((p_row->>''shopPrice'')::int, shop_price),\n      store_enabled = coalesce((p_row->>''storeEnabled'')::boolean, store_enabled),\n      base_multiplier = coalesce((p_row->>''baseMultiplier'')::numeric, base_multiplier),\n      conditional_multiplier = coalesce((p_row->>''conditionalMultiplier'')::numeric, conditional_multiplier),\n      condition_type = coalesce(cond, condition_type),\n      condition_config = coalesce(p_row->''conditionConfig'', condition_config),\n      guaranteed_capture = coalesce((p_row->>''guaranteed'')::boolean, guaranteed_capture),\n      updated_at = now()\n    where key = k;\n  elsif exists (select 1 from public.capture_berries where key = k) then\n    update public.capture_berries set\n      name = coalesce(nullif(p_row->>''name'',''''), name),\n      rpg_description = coalesce(p_row->>''description'', rpg_description),\n      rarity = coalesce(nullif(p_row->>''rarity'',''''), rarity),\n      shop_price = coalesce((p_row->>''shopPrice'')::int, shop_price),\n      store_available = coalesce((p_row->>''storeEnabled'')::boolean, store_available),\n      capture_multiplier = coalesce((p_row->>''baseMultiplier'')::numeric, capture_multiplier),\n      reward_bonus = coalesce((p_row->>''rewardBonus'')::numeric, reward_bonus),\n      updated_at = now()\n    where key = k;\n  else raise exception ''Unknown item.''; end if;\n  return public.admin_item_library(null, null) || jsonb_build_object(''ok'', true, ''message'', ''Item identity saved.'', ''identity'', private.item_identity(k));\nend;'
;
REVOKE ALL ON FUNCTION public.admin_item_definitions_read(),public.admin_item_definitions_save(jsonb),private.hub_item_definition(text,text) FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
